def transform(grid):
    h, w = len(grid), len(grid[0])

    hlines = [r for r in range(h) if grid[r][0] != 0 and all(x == grid[r][0] for x in grid[r])]
    vlines = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]

    def intervals(n, lines):
        spans = []
        start = 0
        for x in lines:
            if start < x:
                spans.append((start, x))
            start = x + 1
        if start < n:
            spans.append((start, n))
        return spans

    rows = intervals(h, hlines)
    cols = intervals(w, vlines)
    out = [row[:] for row in grid]

    def mask(tile, color):
        return tuple(tuple(1 if x == color else 0 for x in row) for row in tile)

    def flip_h(m):
        return tuple(tuple(reversed(row)) for row in m)

    def flip_v(m):
        return tuple(reversed(m))

    for tr in range(len(rows) - 1):
        for tc in range(len(cols) - 1):
            block = [(tr, tc), (tr, tc + 1), (tr + 1, tc), (tr + 1, tc + 1)]
            r0, r1 = rows[tr]
            c0, c1 = cols[tc]
            if rows[tr + 1][1] - rows[tr + 1][0] != r1 - r0:
                continue
            if cols[tc + 1][1] - cols[tc + 1][0] != c1 - c0:
                continue

            colors = set()
            for rr, cc in block:
                a, b = rows[rr]
                x, y = cols[cc]
                colors.update(grid[r][c] for r in range(a, b) for c in range(x, y) if grid[r][c] not in (0, grid[hlines[0]][0] if hlines else -1))

            for color in colors:
                for ar, ac in block:
                    a, b = rows[ar]
                    x, y = cols[ac]
                    source = mask([grid[r][x:y] for r in range(a, b)], color)
                    if not any(any(row) for row in source):
                        continue

                    expected = {}
                    for rr, cc in block:
                        m = source
                        if cc != ac:
                            m = flip_h(m)
                        if rr != ar:
                            m = flip_v(m)
                        expected[(rr, cc)] = m

                    matches = 0
                    for rr, cc in block:
                        a2, b2 = rows[rr]
                        x2, y2 = cols[cc]
                        actual = mask([grid[r][x2:y2] for r in range(a2, b2)], color)
                        if actual == expected[(rr, cc)]:
                            matches += 1

                    if matches >= 3:
