                            x2, y2 = cols[cc]
                            for i in range(b2 - a2):
                                for j in range(y2 - x2):
                                    if expected[(rr, cc)][i][j] and out[a2 + i][x2 + j] == 0:
                                        out[a2 + i][x2 + j] = color
                        break

    return out
